	var bad_writes: Array[String] = []
	for m in re_write.search_all(code):
		var w := "%s.%s" % [m.get_string(1), m.get_string(2)]
		writes.append(w)
		if not (w in ["facing_pivot.transform", "scoot_node.visible", "land_rig.visible"]):
			bad_writes.append(w)
